const fs=require('fs'),vm=require('vm'),ref=process.argv[3],view=fs.readFileSync(ref+'/BrowserOverlayView.swift','utf8'),typ=fs.readFileSync(ref+'/BrowserOverlayTypography.swift','utf8');
const source=view.slice(view.indexOf('    if(opacity===1&&items.length<=256&&rotatedPlates.length>=2)try'),view.indexOf('    // Final plate trim.')).replaceAll('\\\\','\\');
const growth=typ.slice(typ.indexOf('    const aidokuGrowthKeepsLineLength ='),typ.indexOf('    // Line-flow defects'));
const box=r=>({left:r[0],top:r[1],width:r[2],height:r[3],right:r[0]+r[2],bottom:r[1]+r[3]});const turn=(x,y,t)=>[x*Math.cos(t)-y*Math.sin(t),x*Math.sin(t)+y*Math.cos(t)];
function shape(text,font,width,pitch,pad){const adv=font*.55,limit=Math.max(1,Math.floor((width-pad*2)/adv)),rows=[0];for(const word of text.split(' ').filter(Boolean)){let i=rows.length-1;if(rows[i]&&rows[i]+1+word.length>limit){rows.push(0);i++;}else if(rows[i])rows[i]++;rows[i]+=word.length;}return {height:rows.length*pitch,scroll:Math.max(width,Math.max(...rows)*adv+pad*2),lines:rows.map((n,i)=>box([(width-n*adv)/2,i*pitch+(pitch-font)/2,n*adv,font]))};}
const output=JSON.parse(fs.readFileSync(process.argv[2])).map(f=>{
 const root={dataset:{}},items=f.cells.map(c=>({id:c.id,text:c.text,rotation:c.angle,sourceVertical:true,vertical:false,wrappingScript:'korean',sourceFontSize:c.glyph}));
 const nodes=f.cells.map(c=>{
  const style={fontSize:c.font+'px',lineHeight:c.font*1.2+'px',width:c.width+'px',height:c.height+'px',left:'0px',top:'0px',transform:'none',visibility:'visible',padding:'0 0px'};
  Object.defineProperty(style,'cssText',{get(){return Object.entries(this).map(([k,v])=>k.replace(/[A-Z]/g,x=>'-'+x.toLowerCase())+': '+v+';').join('');},set(s){for(const p of s.split(';')){const [k,v]=p.split(':');if(k&&v)this[k.trim().replace(/-([a-z])/g,(_,x)=>x.toUpperCase())]=v.trim();}},enumerable:false});
  return {c,style,dataset:{aidokuRegion:c.id,rotatedPlate:'separate'},childElementCount:0,textContent:c.text,_shape(){return shape(this.textContent,parseFloat(style.fontSize),parseFloat(style.width),parseFloat(style.lineHeight),parseFloat(style.padding.split(' ')[1]));},get scrollWidth(){return this._shape().scroll;},get clientWidth(){return parseFloat(style.width);},getBoundingClientRect(){return box([parseFloat(style.left),parseFloat(style.top),parseFloat(style.width),style.height==='auto'?this._shape().height:parseFloat(style.height)]);},_lines(){const q=this.getBoundingClientRect(),angle=parseFloat(style.transform.match(/rotate\(([^)]+)/)?.[1])||0;return this._shape().lines.map(r=>{const pts=[[r.left,r.top],[r.right,r.top],[r.left,r.bottom],[r.right,r.bottom]].map(([x,y])=>turn(x-q.width/2,y-q.height/2,angle)).map(([x,y])=>[x+q.left+q.width/2,y+q.top+q.height/2]);const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]);return box([Math.min(...xs),Math.min(...ys),Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys)]);});}};
 });
 const foreign=(f.foreign||[]).map(r=>({dataset:{aidokuRegion:r.id},style:{visibility:'visible'},_lines(){return [box(r.rect)];}}));
 root.querySelectorAll=()=>nodes.concat(foreign);
 const plates=f.cells.map(c=>({dataset:{aidokuRegion:c.id},parentElement:root,style:{width:c.width+'px',height:c.height+'px',transform:'rotate('+c.angle+'rad)',backgroundColor:'rgb('+c.color.join(',')+')'},getBoundingClientRect(){const w=Math.abs(c.width*Math.cos(c.angle))+Math.abs(c.height*Math.sin(c.angle)),h=Math.abs(c.width*Math.sin(c.angle))+Math.abs(c.height*Math.cos(c.angle));return box([c.center[0]-w/2,c.center[1]-h/2,w,h]);}}));
 const c={root,items,rotatedPlates:plates,opacity:1,cleanupImageGeometry:{frame:[0,0,500,500]},performance:{now:()=>0},scrollX:0,scrollY:0,getComputedStyle:n=>n.style,document:{createRange:()=>({selectNodeContents(n){this.node=n;},getClientRects(){return this.node._lines();},getBoundingClientRect(){const rs=this.getClientRects(),l=Math.min(...rs.map(r=>r.left)),t=Math.min(...rs.map(r=>r.top)),r=Math.max(...rs.map(r=>r.right)),b=Math.max(...rs.map(r=>r.bottom));return box([l,t,r-l,b-t]);}})}};
 vm.createContext(c);vm.runInContext(growth+source,c);if(root.dataset.displayGroupError)throw Error(root.dataset.displayGroupError);
 const states=nodes.filter(n=>n.dataset.displayGroup).map(n=>{const d=JSON.parse(n.dataset.displayGroup),r=n.getBoundingClientRect();return {id:n.c.id,members:d.members,order:d.order,from:d.from,font:d.size,pitch:parseFloat(n.style.lineHeight),padding:parseFloat(n.style.padding.split(' ')[1]),rect:[r.left,r.top,r.width,r.height],angle:parseFloat(n.style.transform.match(/rotate\(([^)]+)/)[1]),lines:n._lines().map(r=>[r.left,r.top,r.width,r.height])};});
 states.sort((a,b)=>a.members.join('|').localeCompare(b.members.join('|'))||a.order-b.order);
 return {name:f.name,groups:Number(root.dataset.displayGroups||0),states};
});fs.writeFileSync(process.argv[4],JSON.stringify(output));
